package parser

import "strings"

func ParsePair(s string) (string, string, bool) {
	k, v, ok := strings.Cut(s, "=")
	if !ok {
		return "", "", false
	}

	return k, v, true
}

package parser

import "testing"

func TestParsePair(t *testing.T) {
	k, v, ok := ParsePair(" host = localhost ")
	if !ok || k != "host" || v != "localhost" {
		t.Fatalf("got (%q, %q, %v), want (host, localhost, true)", k, v, ok)
	}
}

